INSERT INTO site_settings (id, site_title_vi, site_description_vi, seo_keywords_vi, og_image_url, twitter_handle, github_url, linkedin_url, email, created_at, updated_at, site_title_en, site_description_en, seo_keywords_en, resume_url, phone) VALUES (1, 'Trần Minh Hiểu | AI Software Engineer', 'AI Software Engineer định hướng Nghiên cứu & Kỹ nghệ Giải pháp AI (Applied AI Research & Engineering). Chuyên sâu về Graph Neural Networks, Advanced RAG, Hybrid Search và kiến trúc phần mềm AI thực tế.', 'Trần Minh Hiểu,Tran Minh Hieu,AI Software Engineer,Applied AI Researcher,Graph Neural Networks,Representation Learning,Advanced RAG,Hybrid Search,FastAPI,PyTorch Geometric,Python,Portfolio', '', '', 'https://github.com/Tmh3101', 'https://linkedin.com/in/tmh3101', 'hieutm.site@gmail.com', '2026-03-15T17:03:18.365486+00:00', '2026-09-30T15:57:53.477858+00:00', 'Tran Minh Hieu | AI Software Engineer', 'AI Software Engineer specializing in Applied AI Research & Engineering. Bridging theoretical machine learning (Graph Neural Networks, Advanced RAG, Representation Learning) with production software engineering.', 'Tran Minh Hieu,AI Software Engineer,Applied AI Researcher,Graph Neural Networks,Representation Learning,Advanced RAG,Hybrid Search,FastAPI,PyTorch Geometric,Python,Portfolio', 'https://uhhmsyhsbcvfvilphwdk.supabase.co/storage/v1/object/public/portfolio-assets/cv/CV_TranMinhHieu.pdf', NULL);
INSERT INTO hero_section (id, greeting_vi, name, headline_vi, subheadline_vi, roles_vi, avatar_url, cta_primary_label_vi, cta_primary_href, cta_secondary_label_vi, cta_secondary_href, created_at, updated_at, greeting_en, headline_en, subheadline_en, roles_en, cta_primary_label_en, cta_secondary_label_en, subtitle_vi, subtitle_en, role1_label_vi, role1_label_en, role2_label_vi, role2_label_en, role3_label_vi, role3_label_en) VALUES (1, 'Xin chào, tôi là', 'Trần Minh Hiểu', 'AI Software Engineer', 'Kỹ sư Khoa học Máy tính kết hợp nền tảng AI/ML/DL chuyên sâu với tư duy kỹ thuật phần mềm vững chắc — tập trung nghiên cứu và hiện thực hóa các giải pháp AI cùng công nghệ phân tán (Blockchain/Web3) vào giải quyết bài toán thực tế.', 'AI / Software,Đại học Cần Thơ,Khoa học máy tính', '/avatars/hieutm.jpg', 'Xem CV', 'https://uhhmsyhsbcvfvilphwdk.supabase.co/storage/v1/object/public/portfolio-assets/cv/CV_TranMinhHieu.pdf', 'Liên hệ', '#contact', '2026-03-15T17:07:04.237823+00:00', '2026-09-30T17:59:27.058945+00:00', 'Hi, I am', 'AI Software Engineer', 'Engineer in Computer Science combining a solid foundation in AI/ML/DL with robust software engineering — focused on researching and integrating AI solutions and decentralized technologies (Blockchain/Web3) to solve real-world problems.', 'AI / Software,Can Tho University,Computer Science', NULL, NULL, 'Software Engineering & Applied AI', 'Software Engineering & Applied AI', 'Tập trung', 'Focus', 'Tốt nghiệp', 'Graduated', 'Chuyên ngành', 'Major');
INSERT INTO experience_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, current_role_label_vi, current_role_label_en, earlier_roles_label_vi, earlier_roles_label_en, earlier_roles_copy_vi, earlier_roles_copy_en, education_label_vi, education_label_en, highlights_label_vi, highlights_label_en, created_at, updated_at) VALUES (1, 'Hành trình', 'Journey', 'Kinh nghiệm', 'Professional', 'làm việc', 'Experience', 'Hành trình từ khi còn là sinh viên đến khi trở thành Backend Developer, tập trung vào việc xây dựng các hệ thống ổn định và có khả năng mở rộng.', 'A journey from student years to Backend Developer, focusing on building stable and scalable systems.', 'Vai trò hiện tại', 'Current role', 'Các chặng trước', 'Earlier roles', 'Những vai trò trước đó tạo nền cho cách tôi xây backend systems hôm nay.', 'The earlier roles that shaped how I approach backend systems today.', 'Học vấn', 'Education', 'Điểm chính', 'Highlights', '2026-03-17T07:48:51.662793+00:00', '2026-03-17T07:48:51.662793+00:00');
INSERT INTO skill_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, created_at, updated_at) VALUES (1, 'Kỹ năng', 'Skills', 'Công nghệ tôi dùng', 'Tech I work with', 'tôi sử dụng', 'Stack', 'Ngôn ngữ, framework, database và công cụ cloud tôi dùng để ship sản phẩm backend & AI.', 'Languages, frameworks, databases and cloud tooling I use to ship backend & AI products.', '2026-03-17T06:15:44.607856+00:00', '2026-08-16T07:51:38.152029+00:00');
INSERT INTO approach_section (id, eyebrow_vi, eyebrow_en, title1_vi, title1_en, title2_vi, title2_en, description_vi, description_en, note_label_vi, note_label_en, note_vi, note_en, created_at, updated_at) VALUES (1, 'ABOUT ME', 'ABOUT ME', 'Kỹ nghệ Hệ thống &', 'Software Engineering &', 'Ứng dụng AI Thực tế', 'Applied AI Systems', 'Tôi là một AI Software Engineer với nền tảng Khoa học Máy tính vững chắc, tập trung vào việc thiết kế và vận hành các hệ thống phần mềm có độ ổn định cao. Tôi tiếp cận AI dưới góc nhìn của một kỹ sư xây dựng sản phẩm: 70% tập trung vào kiến trúc hệ thống, API chuẩn mực, hàng đợi bất đồng bộ và tính toàn vẹn dữ liệu; 30% tập trung vào việc thử nghiệm, tinh chỉnh các mô hình học máy và giải pháp RAG nâng cao để phục vụ trực tiếp bài toán kinh doanh.', 'I am an AI Software Engineer with a solid Computer Science background, dedicated to architecting and operating resilient software systems. I approach AI from a product engineer''s perspective: 70% focused on system architecture, robust APIs, asynchronous queues, and data integrity; 30% focused on experimenting, fine-tuning machine learning models, and advanced RAG architectures that directly solve business problems.', 'ROLE MỤC TIÊU', 'TARGET ROLE', 'AI Software Engineer / Backend Engineer tại các đội ngũ phát triển sản phẩm SaaS, FinTech hoặc các phòng R&D ứng dụng — nơi tìm kiếm kỹ sư có tư duy phần mềm bài bản, khả năng tự chủ tính năng và sẵn sàng đưa AI ra môi trường production.', 'AI Software Engineer / Backend Engineer in SaaS, FinTech, or applied R&D teams seeking engineers with structured software craftsmanship, strong ownership, and the ability to deploy AI into production environments.', '2026-03-17T05:56:08.169847+00:00', '2026-09-30T16:43:55.618841+00:00');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (2, 'Production RAG & Tìm kiếm Ngữ nghĩa', 'APPLIED AI & RETRIEVAL', 'Thiết kế luồng RAG end-to-end cho sản phẩm thực tế: triển khai Hybrid Search kết hợp vector embeddings (pgvector) với Full-text search (BM25) qua cơ chế Reciprocal Rank Fusion. Xây dựng pipeline bóc tách dữ liệu ngầm và tối ưu hóa context retrieval nhằm hạn chế tối đa ảo giác thông tin (hallucination).', '', 1, '2026-03-17T05:59:15.492065+00:00', '2026-09-30T16:43:55.961811+00:00', 'Production RAG & Semantic Retrieval', 'APPLIED AI & RETRIEVAL', 'Architecting end-to-end RAG workflows for production: deploying Hybrid Search combining vector embeddings (pgvector) and sparse BM25 indexing via Reciprocal Rank Fusion. Implementing background ingestion pipelines and context reranking to eliminate hallucinations.');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (3, 'Hạ tầng Backend & Hệ thống Bất đồng bộ', 'SOFTWARE & DISTRIBUTED SYSTEMS', 'Xây dựng RESTful API phân tầng sạch sẽ, đa người thuê (Multi-tenant) và bảo vệ an toàn bằng Rate Limiting, CORS, Token Lifecycle. Triển khai hàng đợi tác vụ nền với Redis & BullMQ chịu lỗi cao, tích hợp cổng thanh toán bên thứ ba bảo đảm tính toàn vẹn dữ liệu (zero data loss).', '', 2, '2026-03-17T05:59:58.41027+00:00', '2026-09-30T16:43:56.230216+00:00', 'Backend Infrastructure & Async Queues', 'SOFTWARE & DISTRIBUTED SYSTEMS', 'Building clean, layered, multi-tenant RESTful APIs secured with Rate Limiting, CORS, and Token Lifecycles. Engineering fault-tolerant background queues with Redis & BullMQ, and integrating third-party payment gateways with strict zero-data-loss guarantees.');
INSERT INTO approaches (id, title_vi, subtitle_vi, description_vi, icon, sort_order, created_at, updated_at, title_en, subtitle_en, description_en) VALUES (4, 'Mô hình hóa Dữ liệu & Machine Learning', 'DATA MODELING & GRAPH EXPLORATION', 'Khai thác và tiền xử lý dữ liệu quy mô lớn qua Google BigQuery. Khảo sát và ứng dụng các kỹ thuật biểu diễn dữ liệu phức tạp (Graph Neural Networks - GATv2, Graph Autoencoder) để nhận diện bất thường, kết hợp mô hình phân lớp truyền thống để giải quyết bài toán mất cân bằng nhãn dữ liệu.', '', 3, '2026-03-17T06:00:21.343968+00:00', '2026-09-30T16:43:56.414957+00:00', 'Data Modeling & Machine Learning', 'DATA MODELING & GRAPH EXPLORATION', 'Extracting and preprocessing large-scale datasets via Google BigQuery. Implementing graph representation learning (Graph Neural Networks - GATv2, Graph Autoencoders) for anomaly detection, coupled with ensemble classifiers to resolve severe class imbalance.');
