INSERT INTO stats (id, label_vi, value, suffix, sort_order, created_at, updated_at, label_en, copy_vi, copy_en, icon) VALUES (3, 'Dự án Production & R&D', 5, '+', 3, '2026-03-16T16:32:26.179702+00:00', '2026-09-30T16:43:57.125989+00:00', 'Production & R&D Projects', 'SaaS, Distributed, AI', 'SaaS, Distributed, AI', 'Rocket');
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (3, 'vielora', 'Vielora - AI Chatbot SaaS Platform', 'Nền tảng AI Chatbot SaaS Multi-tenant & RAG Pipeline', 'Xây dựng hệ thống SaaS Multi-tenant hoàn chỉnh: RAG pipeline với hybrid search (vector + full-text), hàng đợi Redis/BullMQ cào dữ liệu ngầm không block luồng chính, tích hợp thanh toán tự động payOS và xuất hóa đơn điện tử EasyInvoice.', '/assets/optimized/vielora.webp', NULL, 'https://vielora.vn', 'Next.js 14,TypeScript,Supabase,pgvector,Redis,BullMQ,Docker,Gemini API', true, 0, '2026-08-16T07:51:47.579392+00:00', '2026-09-30T16:43:57.54547+00:00', 'Vielora - AI Chatbot SaaS Platform', 'Multi-tenant AI Chatbot SaaS & RAG Pipeline', 'End-to-end multi-tenant SaaS: RAG pipeline with hybrid search (pgvector + full-text), async Redis/BullMQ ingestion queue, automated payOS checkout and EasyInvoice VAT generation.', NULL, 'Multi-tenant,Hybrid Search,Async Queue,payOS & EasyInvoice', 'Multi-tenant,Hybrid Search,Async Queue,payOS & EasyInvoice', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (4, 'xpervia', 'Xpervia - AI LMS & Recommender Engine', 'Nền tảng quản lý học tập tích hợp RAG Assistant & Gợi ý khóa học', 'Thực nghiệm đối sánh hiệu quả giữa Vanilla RAG và HyDE RAG; fine-tune mô hình ngôn ngữ mã nguồn mở Qwen2.5-1.5B trên dữ liệu bài học; xây dựng bộ gợi ý khóa học lai (Collaborative + Content-based).', '/assets/optimized/xpervia.webp', 'https://github.com/Tmh3101/xpervia', 'https://xpervia.vercel.app', 'Django,DRF,Next.js,LangChain,Qwen2.5,PostgreSQL', false, 5, '2026-08-16T07:51:47.579392+00:00', '2026-09-30T16:43:58.802478+00:00', 'Xpervia - AI LMS & Recommender Engine', 'Learning Management System & AI RAG Chatbot', 'Empirical comparison of Vanilla RAG vs. HyDE RAG; fine-tuned open-source Qwen2.5-1.5B on lesson domain data; built hybrid course recommender (Collaborative + Content-based filtering).', NULL, 'Vanilla vs HyDE RAG,Qwen2.5-1.5B Fine-tuning,Hybrid Recommender,RBAC', 'Vanilla vs HyDE RAG,Qwen2.5-1.5B Fine-tuning,Hybrid Recommender,RBAC', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (5, 'sybilsignal', 'SybilSignal - Graph-based Risk Detection', 'Hệ thống phát hiện tài khoản bất thường on-chain bằng Graph AI (9.8/10)', 'Trích xuất và tiền xử lý hàng triệu bản ghi on-chain Lens Protocol từ BigQuery sang đồ thị 4 tầng. Thiết kế kiến trúc tách rời (GATv2 + Random Forest) hóa giải hiện tượng over-smoothing và mất cân bằng nhãn; dashboard Next.js + FastAPI trực quan hóa Attention Weights.', '/assets/optimized/sybilsignal.webp', 'https://github.com/Tmh3101/sybilsignal-app', 'https://sybilsignal.vercel.app', 'Python,PyTorch Geometric,FastAPI,BigQuery,Modal,Next.js', true, 2, '2026-08-16T07:51:47.579392+00:00', '2026-09-30T16:43:58.2953+00:00', 'SybilSignal - Graph-based Risk Detection', 'Graph-based Web3 Fraud Detection (Thesis 9.8/10)', 'Extracted and preprocessed millions of Lens Protocol on-chain records from BigQuery into 4-layer graph. Decoupled GATv2 + Random Forest architecture resolving over-smoothing and label imbalance; Next.js + FastAPI dashboard visualizing Attention Weights.', NULL, 'GATv2 Graph Neural Network,Decoupled GNN-ML,XAI Attention Weights,BigQuery Pipeline', 'GATv2 Graph Neural Network,Decoupled GNN-ML,XAI Attention Weights,BigQuery Pipeline', 'https://drive.google.com/file/d/1YOmJeSeUQA0xQq--tOlI6aosKq5rHam8/view?usp=sharing');
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (6, 'slice-socialfi', 'Slice SocialFi - Token Bridge & Task Queue', 'Cầu nối tài sản Cross-chain & Hệ thống xử lý giao dịch an toàn', 'Thiết kế cầu nối token cross-chain giữa BNB Smart Chain và LensChain (Lock/Mint & Burn/Unlock). Xây dựng hàng đợi tác vụ Redis xử lý luồng giao dịch Fiat-to-Crypto bảo đảm tính toàn vẹn dữ liệu (zero data loss); container hóa Docker trên AWS EC2.', '/assets/optimized/slice-socialfi.webp', NULL, 'https://slicefi.xyz/', 'Node.js,Hono,Viem,Solidity,Redis,PostgreSQL,AWS EC2,Docker', true, 1, '2026-09-30T09:21:55.037857+00:00', '2026-09-30T16:43:58.086191+00:00', 'Slice SocialFi - Token Bridge & Task Queue', 'Cross-chain Token Bridge & Async Transaction Processing', 'Cross-chain token bridge between BNB Smart Chain and LensChain (Lock/Mint & Burn/Unlock). Redis task queue handling Fiat-to-Crypto transactions guaranteeing zero data loss; containerized Docker microservices on AWS EC2.', NULL, 'Cross-chain Token Bridge,Zero-data-loss Redis Queue,DNPAY Fiat-to-Crypto,AWS EC2', 'Cross-chain Token Bridge,Zero-data-loss Redis Queue,DNPAY Fiat-to-Crypto,AWS EC2', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (7, 'giftcards', 'Giftcards.vn - Corporate Gift Solutions', 'Giải pháp quà tặng doanh nghiệp & Cổng thanh toán', 'Tích hợp cổng thanh toán DNPAY Merchant, thiết kế cơ chế retry payment flow giảm thiểu tỷ lệ rớt đơn hàng, quản lý vòng đời đơn hàng quà tặng doanh nghiệp.', '/assets/optimized/giftcards.webp', NULL, NULL, 'NestJS,MongoDB,Redis,ReactJS', false, 3, '2026-09-30T09:21:55.431521+00:00', '2026-09-30T16:43:58.446364+00:00', 'Giftcards.vn - Corporate Gift Solutions', 'Corporate Gift Solutions & Payment Gateway', 'Integrated DNPAY Merchant payment gateway, designed payment retry mechanism minimizing cart abandonment rate, managed corporate gift order lifecycle.', NULL, 'DNPAY Merchant Gateway,Payment Retry Flow,Order Lifecycle Management', 'DNPAY Merchant Gateway,Payment Retry Flow,Order Lifecycle Management', NULL);
INSERT INTO projects (id, slug, title_vi, short_description_vi, description_vi, thumbnail_url, repo_url, live_url, technologies, featured, sort_order, created_at, updated_at, title_en, short_description_en, description_en, images_url, features_vi, features_en, report_url) VALUES (8, 'identity-service', 'Enterprise Identity & Auth Microservice', 'Hệ thống định danh & phân quyền bảo mật cao bằng Java Spring Boot 3', 'Xây dựng dịch vụ định danh người dùng chuẩn RESTful theo kiến trúc phân tầng sạch sẽ. Triển khai xác thực JWT + OAuth2, phân quyền RBAC, cơ chế băm mật khẩu, xoay vòng refresh token và token revocation list.', '/assets/optimized/identity-service.webp', 'https://github.com/Tmh3101/user-service', NULL, 'Java 17,Spring Boot 3,Spring Security,OAuth2,JWT,MySQL,Docker', false, 4, '2026-09-30T09:21:55.860191+00:00', '2026-09-30T16:43:58.64859+00:00', 'Enterprise Identity & Auth Microservice', 'High-Security Enterprise Auth Microservice', 'RESTful identity service following clean layered architecture. Implemented JWT + OAuth2 authentication, RBAC authorization, password hashing, refresh token rotation, and token revocation list.', NULL, 'JWT + OAuth2 Auth,Brute-force Protection,Token Revocation List,Layered Architecture', 'JWT + OAuth2 Auth,Brute-force Protection,Token Revocation List,Layered Architecture', NULL);
